class Solution {
public:
    int line(vector<int>& nums, int lo, int hi) {
        int take = 0, skip = 0;
        for (int i = lo; i <= hi; i++) {
            int nt = skip + nums[i];
            skip = max(skip, take);
            take = nt;
        }
        return max(take, skip);
    }
    int rob(vector<int>& nums) {
        int n = nums.size();
        if (n == 1) return nums[0];
        return max(line(nums, 0, n - 2), line(nums, 1, n - 1));
    }
};
